const p = $json.parsed || {};
let text = "";
if (typeof p === "string") { text = p; }
else if (typeof p.transcript_text === "string" && p.transcript_text) { text = p.transcript_text; }
else if (Array.isArray(p.utterances) && p.utterances.length) { text = p.utterances.map(function (u) { return "Speaker " + (u.speaker || "") + ": " + (u.text || ""); }).join("\n"); }
else if (typeof p.transcript === "string" && p.transcript) { text = p.transcript; }
else if (typeof p.text === "string" && p.text) { text = p.text; }
if (!text) { text = JSON.stringify(p, null, 2); }
return [{ json: { transcript_text: text } }];

