parameters.jsCode:
let data = ($json.output && $json.output[0] && $json.output[0].content && $json.output[0].content[0])
  ? $json.output[0].content[0].text
  : $json;
if (typeof data === "string") { try { data = JSON.parse(data); } catch (e) { data = {}; } }
data = data || {};
const form = $("Meeting Intake Form").item.json;
const title = form.meeting_title || "Meeting";
const emails = form.participant_emails || "";
const summary = data.summary || {};
const decisions = Array.isArray(data.decisions) ? data.decisions : [];
const risks = Array.isArray(data.risks) ? data.risks : [];
const parking = Array.isArray(data.parking_lot) ? data.parking_lot : [];
const follow = data.follow_up_meeting || {};
const rawActions = Array.isArray(data.action_items) ? data.action_items : [];
const actions = rawActions.map(function (a) {
  const t = a.title || "Action item";
  const asg = a.assignee || "Unassigned";
  const dl = a.deadline || "No deadline";
  const pr = a.priority || "Medium";
  const det = a.details || "";
  const st = a.status || "New";
  const pn = a.progress_note || "";
  const hu = /progress|complet/i.test(st);
  const desc = "Action: " + t + "\nAssignee: " + asg + "\nDeadline: " + dl + "\nPriority: " + pr + "\n\n" + det + "\n\nMeeting: " + title;
  return { title: t, assignee: asg, deadline: dl, priority: pr, details: det, status: st, progress_note: pn, has_update: hu, meeting_title: title, jira_summary: "[" + pr + "] " + t + " (" + asg + ")", jira_description: desc };
});
const esc = function (s) { return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); };
const parts = [];
parts.push("<h2>Meeting Summary: " + esc(title) + "</h2>");
parts.push("<p>" + esc(summary.overview || "") + "</p>");
if (Array.isArray(summary.key_topics) && summary.key_topics.length) {
  parts.push("<p><b>Key topics:</b> " + summary.key_topics.map(esc).join(", ") + "</p>");
}
const email_top = parts.join("\n");
parts.push("<h3>Action Items</h3>");
const ai_index = parts.length;
if (actions.length) {
  parts.push("<ul>" + actions.map(function (a) { return "<li><b>" + esc(a.title) + "</b> - " + esc(a.assignee) + " | due " + esc(a.deadline) + " | " + esc(a.priority) + "</li>"; }).join("") + "</ul>");
} else { parts.push("<p>None.</p>"); }
parts.push("<h3>Decisions</h3>");
if (decisions.length) {
  parts.push("<ul>" + decisions.map(function (d) { return "<li>" + esc(d.decision) + (d.rationale ? " - " + esc(d.rationale) : "") + "</li>"; }).join("") + "</ul>");
} else { parts.push("<p>None.</p>"); }
parts.push("<h3>Risks &amp; Blockers</h3>");
if (risks.length) {
  parts.push("<ul>" + risks.map(function (r) { return "<li>" + esc(r.risk) + (r.impact ? " - " + esc(r.impact) : "") + "</li>"; }).join("") + "</ul>");
} else { parts.push("<p>None.</p>"); }
if (follow && follow.needed) {
  parts.push("<h3>Follow-up Meeting</h3><p>" + esc(follow.suggested_topic || "") + " (" + esc(follow.suggested_timeframe || "") + ")</p>");
}
if (parking.length) {
  parts.push("<h3>Parking Lot</h3><ul>" + parking.map(function (p) { return "<li>" + esc(p) + "</li>"; }).join("") + "</ul>");
}
const email_html = parts.join("\n");
const email_bottom = parts.slice(ai_index + 1).join("\n");
return { json: { meeting_title: title, participant_emails: emails, summary: summary, decisions: decisions, risks: risks, follow_up_meeting: follow, parking_lot: parking, action_items: actions, email_html: email_html, email_top: email_top, email_bottom: email_bottom, structured_json: data } };

